    let colorR: Double?
    let colorG: Double?
    let colorB: Double?
    let colorA: Double?

    enum ValidationError: Error {
        case invalidIdentifier
        case invalidRequiredNumber
        case invalidOptionalNumber
        case invalidSize
        case invalidOpacity
        case invalidColorComponent
        case incompleteTransform
    }

    var frame: CGRect {
        CGRect(x: CGFloat(x), y: CGFloat(y), width: CGFloat(width), height: CGFloat(height))
