    var resolvedOpacity: CGFloat {
        CGFloat(max(0, min(1, opacity)))
    }

    var resolvedZIndex: CGFloat {
        CGFloat(zIndex)
    }

    var hasTransform: Bool {
        transformA != nil &&
        transformB != nil &&
        transformC != nil &&
        transformD != nil &&
        transformTX != nil &&
        transformTY != nil
    }

    var affineTransform: CGAffineTransform {
        guard
            let a = transformA,
            let b = transformB,
            let c = transformC,
            let d = transformD,
            let tx = transformTX,
            let ty = transformTY
        else {
            return .identity
        }

        return CGAffineTransform(
            a: CGFloat(a),
            b: CGFloat(b),
            c: CGFloat(c),
            d: CGFloat(d),
            tx: CGFloat(tx),
            ty: CGFloat(ty)
        )
    }

    var resolvedColor: UIColor? {
        guard
            let r = colorR,
            let g = colorG,
            let b = colorB,
            let a = colorA
        else {
            return nil
        }

        return UIColor(
            red: CGFloat(max(0, min(1, r))),
            green: CGFloat(max(0, min(1, g))),
            blue: CGFloat(max(0, min(1, b))),
            alpha: CGFloat(max(0, min(1, a)))
        )
    }

    func validated() throws -> LayoutElement {
        guard !id.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw ValidationError.invalidIdentifier
        }

        let requiredValues = [
            x,
            y,
            width,
            height,
            borderRadius,
            opacity,
            zIndex
        ]

        guard requiredValues.allSatisfy(\.isFinite) else {
            throw ValidationError.invalidRequiredNumber
        }

        guard width >= 0, height >= 0, borderRadius >= 0 else {
            throw ValidationError.invalidSize
        }

        guard opacity >= 0, opacity <= 1 else {
            throw ValidationError.invalidOpacity
        }

        let optionalValues = [
            fontSize,
            lineHeight,
            paddingTop,
            paddingLeft,
            paddingRight,
            paddingBottom,
            scrollY,
            transformA,
            transformB,
            transformC,
            transformD,
            transformTX,
            transformTY,
            colorR,
            colorG,
            colorB,
            colorA
        ]

        guard optionalValues.allSatisfy({ $0?.isFinite ?? true }) else {
            throw ValidationError.invalidOptionalNumber
        }

        let transformValues = [
            transformA,
            transformB,
            transformC,
            transformD,
            transformTX,
            transformTY
        ]

        let transformCount = transformValues.compactMap { $0 }.count

        guard transformCount == 0 || transformCount == transformValues.count else {
            throw ValidationError.incompleteTransform
        }

        let colorValues = [colorR, colorG, colorB, colorA]
        let colorCount = colorValues.compactMap { $0 }.count

        guard colorCount == 0 || colorCount == colorValues.count else {
            throw ValidationError.invalidColorComponent
        }

        guard colorValues.allSatisfy({ value in
            guard let value else {
                return true
            }

            return value >= 0 && value <= 1
        }) else {
            throw ValidationError.invalidColorComponent
        }

        return self
    }
}

struct LayoutPayload: Codable, Sendable {
    let elements: [LayoutElement]
    let timestamp: Double
    let devicePixelRatio: Double
    let scrollY: Double?
    let viewportWidth: Double?
    let viewportHeight: Double?

    enum ValidationError: Error {
        case invalidTimestamp
        case invalidDevicePixelRatio
        case invalidScrollPosition
        case invalidViewportDimension
        case duplicateElementIdentifier
    }

    func validated() throws -> LayoutPayload {
        guard timestamp.isFinite else {
            throw ValidationError.invalidTimestamp
        }

        guard devicePixelRatio.isFinite, devicePixelRatio > 0 else {
            throw ValidationError.invalidDevicePixelRatio
        }

        if let scrollY {
            guard scrollY.isFinite else {
                throw ValidationError.invalidScrollPosition
            }
        }

        for dimension in [viewportWidth, viewportHeight] {
            if let dimension {
                guard dimension.isFinite, dimension >= 0 else {
                    throw ValidationError.invalidViewportDimension
                }
            }
        }

        let identifiers = elements.map(\.id)

        guard Set(identifiers).count == identifiers.count else {
            throw ValidationError.duplicateElementIdentifier
        }

        try elements.forEach { element in
            _ = try element.validated()
        }

        return self
    }
}

