    func updateFrameCache(with payload: LayoutPayload) {
        let scale = CGFloat(payload.devicePixelRatio)
        let payloadScrollY = CGFloat(payload.scrollY ?? 0)

        frameCache = Dictionary(
            uniqueKeysWithValues: payload.elements.map { element in
                let elementScrollY = CGFloat(element.scrollY ?? payloadScrollY)
                let frame = CGRect(
                    x: CGFloat(element.x) / scale,
                    y: (CGFloat(element.y) - elementScrollY) / scale,
                    width: CGFloat(element.width) / scale,
                    height: CGFloat(element.height) / scale
                )

                return (element.id, frame)
            }
        )
    }

    nonisolated func userContentController(
        _ userContentController: WKUserContentController,
        didReceive message: WKScriptMessage
    ) {
        guard message.name == "layoutBridge" else {
            return
        }

        do {
            let data = try Self.data(from: message.body)
            let payload = try Self.decodePayload(from: data)

            Task { @MainActor [weak self] in
                guard let self else {
                    return
                }

                self.pendingPayload = payload
                self.updateFrameCache(with: payload)
                self.delegate?.layoutEngine(self, didReceive: payload)
            }
        } catch {
            Task { @MainActor [weak self] in
                self?.reportError(error)
            }
        }
    }

    private static func data(from body: Any) throws -> Data {
        if let dictionary = body as? [String: Any] {
            guard JSONSerialization.isValidJSONObject(dictionary) else {
                throw NSError(
                    domain: "LayoutBridge",
                    code: 422,
                    userInfo: [
                        NSLocalizedDescriptionKey: "Dictionary payload is not valid JSON."
                    ]
                )
            }

            return try JSONSerialization.data(withJSONObject: dictionary, options: [])
        }

        if let array = body as? [Any] {
            guard JSONSerialization.isValidJSONObject(array) else {
                throw NSError(
                    domain: "LayoutBridge",
                    code: 422,
                    userInfo: [
                        NSLocalizedDescriptionKey: "Array payload is not valid JSON."
                    ]
                )
            }

            return try JSONSerialization.data(withJSONObject: array, options: [])
        }

        if let jsonString = body as? String {
            guard let data = jsonString.data(using: .utf8) else {
                throw NSError(
                    domain: "LayoutBridge",
                    code: 422,
                    userInfo: [
                        NSLocalizedDescriptionKey: "JSON string could not be encoded as UTF-8."
                    ]
                )
            }

            return data
        }

        throw NSError(
            domain: "LayoutBridge",
            code: 422,
            userInfo: [
                NSLocalizedDescriptionKey: "Unexpected body type: \(String(describing: type(of: body)))."
            ]
        )
    }

