final class LayoutBridgeRegistration {
    private let bridge: LayoutBridge
    private let weakHandler: WeakScriptMessageHandler
    private weak var userContentController: WKUserContentController?
    private let name: String
    private var isRegistered = false

    init(
        bridge: LayoutBridge,
        userContentController: WKUserContentController,
        name: String = "layoutBridge"
    ) {
        self.bridge = bridge
        self.userContentController = userContentController
        self.name = name
        self.weakHandler = WeakScriptMessageHandler(delegate: bridge)
    }

    func register() {
        guard !isRegistered, let userContentController else {
            return
        }

        userContentController.add(weakHandler, name: name)
        isRegistered = true
    }

    func unregister() {
        guard isRegistered, let userContentController else {
            return
        }

        userContentController.removeScriptMessageHandler(forName: name)
        isRegistered = false
    }

    deinit {
        if isRegistered {
            userContentController?.removeScriptMessageHandler(forName: name)
        }
    }
