import UIKit
import Metal
import MetalKit
import WebKit
import QuartzCore

@MainActor
final class MetalTextureRedirectView: MTKView {
    enum MetalTextureRedirectViewError: LocalizedError {
        case metalUnavailable
        case commandQueueUnavailable
        case invalidSourceTextureDevice
        case unsupportedSourceTextureUsage
        case sourceTextureUnavailable

        var errorDescription: String? {
            switch self {
            case .metalUnavailable:
                return "Metal is not supported on this device."
            case .commandQueueUnavailable:
                return "Unable to create a Metal command queue."
            case .invalidSourceTextureDevice:
                return "The source texture belongs to a different Metal device."
            case .unsupportedSourceTextureUsage:
                return "The source texture is not available for shader reads."
            case .sourceTextureUnavailable:
                return "No source texture is available."
            }
        }
    }

    private let commandQueue: MTLCommandQueue
    private weak var sourceWebView: WKWebView?
    private var sourceTexture: MTLTexture?
    private var sourceTextureSize: CGSize = .zero
    private var sourceTextureGeneration: UInt64 = 0
    private var renderedTextureGeneration: UInt64 = 0
    private var sourceWebViewObservation: NSKeyValueObservation?
    private var windowObservation: NSKeyValueObservation?
    private var isRendering = false

    init?(frame: CGRect, webView: WKWebView) {
        guard let device = MTLCreateSystemDefaultDevice() else {
            return nil
        }

        guard let commandQueue = device.makeCommandQueue() else {
            return nil
        }

        self.commandQueue = commandQueue

        super.init(frame: frame, device: device)

        isOpaque = false
        backgroundColor = .clear
        layer.isOpaque = false
        clearColor = MTLClearColor(red: 0, green: 0, blue: 0, alpha: 0)
        colorPixelFormat = .bgra8Unorm
        framebufferOnly = false
        autoResizeDrawable = true
        preferredFramesPerSecond = preferredFrameRate(for: UIScreen.main)
        enableSetNeedsDisplay = true
        isPaused = true

        updateSourceWebView(webView)
    }

    required init(coder: NSCoder) {
        return nil
    }

    deinit {
        sourceWebViewObservation?.invalidate()
        windowObservation?.invalidate()
    }

    override func didMoveToWindow() {
        super.didMoveToWindow()

        if let screen = window?.screen {
            preferredFramesPerSecond = preferredFrameRate(for: screen)
        }

        requestDisplay()
    }

    override func layoutSubviews() {
        super.layoutSubviews()
        requestDisplay()
    }

    func updateSourceWebView(_ webView: WKWebView) {
        sourceWebViewObservation?.invalidate()
        sourceWebView = webView
        sourceTexture = nil
        sourceTextureSize = .zero
        sourceTextureGeneration &+= 1
        renderedTextureGeneration = 0

        sourceWebViewObservation = webView.observe(
            \.bounds,
            options: [.initial, .new]
        ) { [weak self] _, _ in
            Task { @MainActor [weak self] in
                self?.requestDisplay()
            }
        }

        requestDisplay()
    }

    func injectWebGLTexture(_ texture: MTLTexture) throws {
        guard let device else {
            throw MetalTextureRedirectViewError.metalUnavailable
        }

        guard texture.device.registryID == device.registryID else {
            throw MetalTextureRedirectViewError.invalidSourceTextureDevice
        }

        guard texture.usage.contains(.shaderRead) else {
            throw MetalTextureRedirectViewError.unsupportedSourceTextureUsage
        }

        sourceTexture = texture
        sourceTextureSize = CGSize(
            width: texture.width,
            height: texture.height
        )
        sourceTextureGeneration &+= 1
        requestDisplay()
    }

    func clearSourceTexture() {
        sourceTexture = nil
        sourceTextureSize = .zero
        sourceTextureGeneration &+= 1
        requestDisplay()
    }

    func requestDisplay() {
        setNeedsDisplay()
    }

    override func draw(_ rect: CGRect) {
        guard !isRendering else {
            return
        }

        isRendering = true
        defer {
            isRendering = false
        }

        guard let sourceTexture else {
            renderClearFrame()
            return
        }

        guard let device else {
            return
        }

        guard sourceTexture.device.registryID == device.registryID else {
            clearSourceTexture()
            renderClearFrame()
            return
        }

        guard sourceTexture.usage.contains(.shaderRead) else {
            clearSourceTexture()
            renderClearFrame()
            return
        }

        render(texture: sourceTexture)
        renderedTextureGeneration = sourceTextureGeneration
    }

    private func renderClearFrame() {
        autoreleasepool {
            guard
                let commandBuffer = commandQueue.makeCommandBuffer(),
                let renderPassDescriptor = currentRenderPassDescriptor,
                let drawable = currentDrawable,
                let encoder = commandBuffer.makeRenderCommandEncoder(
                    descriptor: renderPassDescriptor
                )
            else {
                return
            }

            renderPassDescriptor.colorAttachments[0].loadAction = .clear
            renderPassDescriptor.colorAttachments[0].storeAction = .store
            renderPassDescriptor.colorAttachments[0].clearColor = clearColor

            encoder.endEncoding()
            commandBuffer.present(drawable)
            commandBuffer.commit()
        }
    }

    private func render(texture: MTLTexture) {
        autoreleasepool {
            guard
                let commandBuffer = commandQueue.makeCommandBuffer(),
                let renderPassDescriptor = currentRenderPassDescriptor,
                let drawable = currentDrawable,
                let blitEncoder = commandBuffer.makeBlitCommandEncoder()
            else {
                return
            }

            renderPassDescriptor.colorAttachments[0].loadAction = .clear
            renderPassDescriptor.colorAttachments[0].storeAction = .store
            renderPassDescriptor.colorAttachments[0].clearColor = clearColor

            let destinationTexture = drawable.texture
            let copyWidth = min(texture.width, destinationTexture.width)
            let copyHeight = min(texture.height, destinationTexture.height)

            guard copyWidth > 0, copyHeight > 0 else {
                blitEncoder.endEncoding()

                guard let renderEncoder = commandBuffer.makeRenderCommandEncoder(
                    descriptor: renderPassDescriptor
                ) else {
                    return
                }

                renderEncoder.endEncoding()
                commandBuffer.present(drawable)
                commandBuffer.commit()
                return
            }

            blitEncoder.copy(
                from: texture,
                sourceSlice: 0,
                sourceLevel: 0,
                sourceOrigin: MTLOrigin(
                    x: max((texture.width - copyWidth) / 2, 0),
                    y: max((texture.height - copyHeight) / 2, 0),
                    z: 0
                ),
                sourceSize: MTLSize(
                    width: copyWidth,
                    height: copyHeight,
                    depth: 1
                ),
                to: destinationTexture,
                destinationSlice: 0,
                destinationLevel: 0,
                destinationOrigin: MTLOrigin(
                    x: max((destinationTexture.width - copyWidth) / 2, 0),
                    y: max((destinationTexture.height - copyHeight) / 2, 0),
                    z: 0
                )
            )

            blitEncoder.endEncoding()
            commandBuffer.present(drawable)
            commandBuffer.commit()
        }
    }

    private func preferredFrameRate(for screen: UIScreen) -> Int {
        let maximumFramesPerSecond = screen.maximumFramesPerSecond

        if maximumFramesPerSecond >= 120 {
            return 120
        }

        return max(1, maximumFramesPerSecond)
    }
}
